namespace GeetaStudio.Api;

internal static class CommercePage
{
    internal const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Learning packs and institutional pilot</title>
<style>body{font:18px/1.5 system-ui;max-width:1000px;margin:auto;padding:24px;color:#222;background:#fff9ef}section{border:1px solid #aaa;border-radius:8px;padding:18px;margin:20px 0;background:white}label{display:block;margin:12px 0}input,select,button{font:inherit;padding:8px;max-width:100%}table{width:100%;border-collapse:collapse}td,th{padding:10px;text-align:left;border-bottom:1px solid #bbb}#status{white-space:pre-wrap}</style>
<h1>Learning packs and institutional pilot</h1><p>Private test offers only. Prices, invoices and payment receipts are synthetic; no real customer charge, email, printing or public sale is enabled.</p><label>Workspace <select id="workspace"></select></label><button id="load">Open offers</button><p id="status" role="status" aria-live="polite"></p>
<section><h2>Choose a licensed pack</h2><label>Offer <select id="product"></select></label><p id="terms"></p><label>Purchase for <select id="institution"><option value="">My account</option></select></label><button id="buy">Start test order</button><p>Only verified signed test payment evidence grants access. Every order pins its original content version, license, payment and fulfillment service. Corrections can withhold access; updates do not rewrite past purchases.</p><label>Your orders <select id="order"></select></label><button id="reconcile">Check original payment and delivery</button><button id="download">Download licensed content</button><button id="refund">Request full original refund</button><p id="orderInfo"></p></section>
<section><h2>Institutional pilot</h2><label>Organization name <input id="orgName" maxlength="80"></label><label>Contract reference <input id="contract" value="fixture:private-pilot" maxlength="100"></label><button id="createOrg">Create pilot organization</button><label>Member's shared account reference <input id="member"></label><label>Cohort <input id="cohort" maxlength="80" value="Pilot learners"></label><label>Role <select id="role"><option value="Learner">Learner</option><option value="Administrator">Administrator</option></select></label><label><input type="checkbox" id="seatEnabled" checked> Seat active</label><button id="seat">Save seat change</button><button id="reports">View consented cohort summary</button><button id="institutionDownload">Download institution's licensed pack</button><div id="report"></div><p>Child profiles stay guardian-controlled. Reports disclose observed completion only, require current progress consent and suppress groups with fewer than five subjects.</p></section>
<section><h2>Other offers</h2><div id="offers"></div><p>Merchandise, sponsorship, affiliates, content licensing and ContentOS licensing remain prerequisite-gated. Registering an offer does not create revenue.</p></section>
<script>
const $=x=>document.getElementById(x);let products=[],orders=[],busy=false,pending=null;const op=()=>crypto.randomUUID();const base=()=>'/api/v1/customer/tenants/'+encodeURIComponent($('workspace').value)+'/shop';
async function api(path,body){let r=await fetch(base()+path,{credentials:'same-origin',method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-ContentOS-Staff':'1'},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok)throw Error(await r.text());return r.status===204?null:r.json()}
const run=f=>async()=>{if(busy)return;busy=true;const buttons=document.querySelectorAll('button');buttons.forEach(x=>x.disabled=true);try{await f()}catch(e){$('status').textContent=e.message}finally{busy=false;buttons.forEach(x=>x.disabled=false)}};
function choose(el,rows,label){el.replaceChildren();for(let row of rows){let option=document.createElement('option');option.value=row.id;option.textContent=label(row);el.append(option)}}
function terms(){let p=products.find(x=>x.id===$('product').value);$('terms').textContent=p?`${p.currency} ${(p.priceMinor/100).toFixed(2)} test price · ${p.license.days} days · ${p.license.seats} seats · content version ${p.contentVersion} · ${p.license.updatePolicy} · ${p.license.disclosure}`:'No qualified pilot offer configured'}
function orderInfo(){let o=orders.find(x=>x.id===$('order').value);$('orderInfo').textContent=o?`${o.state} · payment ${o.paymentState} · delivery ${o.deliveryState} · version ${o.contentVersion} · expires ${o.endsUtc||'not granted'}`:'No orders'}
async function load(){products=await api('/products');choose($('product'),products,x=>x.key+' · '+x.kind);terms();orders=await api('/orders');choose($('order'),orders,x=>x.state+' · version '+x.contentVersion);orderInfo();let institutions=await api('/institutions');choose($('institution'),[{id:'',name:'My account'},...institutions],x=>x.name+(x.id?' · '+x.activeSeats+'/'+x.seatCapacity+' licensed seats':''));let offers=await api('/offers');$('offers').replaceChildren();for(let o of offers){let p=document.createElement('p');p.textContent=o.kind+' · '+o.disclosure+' · '+o.prerequisites.join(', ');$('offers').append(p)}$('status').textContent='Private pilot offers loaded'}
$('load').onclick=run(load);$('product').onchange=terms;$('order').onchange=orderInfo;
$('buy').onclick=run(async()=>{let data={productId:$('product').value,institutionId:$('institution').value||null,acquisition:'Unknown'},signature=JSON.stringify(data);if(!pending||pending.signature!==signature)pending={signature,request:{operationId:op(),...data}};let id=await api('/orders',pending.request);await load();$('order').value=id;orderInfo();pending=null});
$('reconcile').onclick=run(async()=>{let id=$('order').value;await api('/orders/'+id+'/reconcile',{});await load();$('order').value=id;orderInfo()});$('download').onclick=run(async()=>{let a=document.createElement('a');a.href=base()+'/orders/'+$('order').value+'/download';a.download='licensed-pack.html';a.click()});
$('refund').onclick=run(async()=>{let o=orders.find(x=>x.id===$('order').value),p=products.find(x=>x.id===o.productId);await api('/orders/'+o.id+'/refund',{operationId:op(),action:'Refund',amountMinor:p.priceMinor});$('status').textContent='Original-provider refund requested. Access changes after authoritative reconciliation.'});
$('createOrg').onclick=run(async()=>{let id=await api('/institutions',{operationId:op(),name:$('orgName').value,contractReference:$('contract').value});await load();$('institution').value=id});$('seat').onclick=run(async()=>{await api('/institutions/'+$('institution').value+'/seats',{operationId:op(),userId:$('member').value,cohort:$('cohort').value,role:$('role').value,enabled:$('seatEnabled').checked});$('status').textContent='Seat change audited'});
$('reports').onclick=run(async()=>{let rows=await api('/institutions/'+$('institution').value+'/cohorts');$('report').replaceChildren();for(let r of rows){let p=document.createElement('p');p.textContent=r.cohort+' · '+r.activeSeats+' seats · completion '+(r.completionRate===null?'suppressed':Math.round(r.completionRate*100)+'%')+' · '+r.coverage;$('report').append(p)}});$('institutionDownload').onclick=run(async()=>{let a=document.createElement('a');a.href=base()+'/institutions/'+$('institution').value+'/products/'+$('product').value+'/download';a.download='institution-pack.html';a.click()});
run(async()=>{let r=await fetch('/api/v1/customer/create/workspaces',{credentials:'same-origin'});if(!r.ok)throw Error(await r.text());choose($('workspace'),await r.json(),x=>x.name);const requested=new URLSearchParams(location.search).get('workspace');if(requested&&Array.from($('workspace').options).some(x=>x.value===requested))$('workspace').value=requested;$('status').textContent='Choose a workspace to open its private pilot offers.'})();
</script></html>
""";
}
